// O app manda o PDF ja pronto em base64 (a inferencia foi paga na interface).
// Aqui ele volta a ser binario para gravacao na pasta sincronizada.
const saida = [];

for (const item of $input.all()) {
  const corpo = item.json.body ?? item.json;
  const b64 = corpo.pdf_base64;

  if (!b64) {
    throw new Error('Payload sem "pdf_base64" - conferir src/n8n.py no projeto.');
  }

  const solicitado = corpo.arquivo || `relatorio_${corpo.paciente || 'sem-id'}.pdf`;
  const nome = solicitado.replace(/[^a-zA-Z0-9._-]/g, '_').replace(/^\.+/, '');
  if (!nome || !nome.toLowerCase().endsWith('.pdf')) {
    throw new Error('Nome de arquivo PDF invalido.');
  }

  saida.push({
    json: {
      paciente: corpo.paciente ?? '',
      pergunta: corpo.pergunta ?? '',
      modelo: corpo.modelo ?? '',
      arquivo: nome,
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(b64, 'base64'),
        nome,
        'application/pdf',
      ),
    },
  });
}

return saida;
